/**
 * Which side of a conversation with the user a line came from.
 */
export type Side = "me" | "them";

/**
 * One row the import wants the person to see: left behind (`skipped`)
 * or imported with a caveat (`notes`). Same shape so the window can
 * word the list, not the row.
 */
export type Skipped = { item: string, reason: string, };

export type SlashCommand = { name: string, description?: string, hint?: string, };

/**
 * `streamDelta`: text arriving as the agent writes it. Never persisted — the
 * durable line is the `TranscriptEvent` that lands when the message is whole.
 */
export type StreamDelta = { "type": "agent_delta", personaId: string, messageId: string, text: string, } | { "type": "thought_delta", personaId: string, messageId: string, text: string, };

/**
 * Overrides for the built-in task runner (`kind: generic`).
 */
export type SubagentDefaults = { name?: string, description?: string, 
/**
 * Extra briefing appended to the silent-runner prompt.
 */
prompt?: string, 
/**
 * Optional model as provider/id. Absent means inherit the teammate's.
 */
modelId?: string, };

/**
 * An extra subagent the parent can pass as `kind`.
 */
export type SubagentSpec = { id: string, name: string, description: string, prompt?: string, modelId?: string, };

/**
 * What a subscription is a subscription to: a stream, or a view the core
 * maintains and nobody logs.
 *
 * Externally tagged, so a stream reads as the word or the pair naming it —
 * `"room"`, `{"tape": "<personaId>"}`, `{"thread": "<key>"}`, `{"view":
 * "roster"}` — which is the shape the window would have written by hand.
 */
export type Target = "room" | { "tape": string } | { "thread": string } | { "view": ViewName };

/**
 * Everything Toad knows about one teammate's tools, and how it knows it.
 */
export type TeammateToolLedger = { personaId: string, agentKind: AgentKind, backendId: string, 
/**
 * When the session that produced this ledger started.
 */
at: number, rows: Array<ToolLedgerRow>, };

/**
 * One hit from a thread search: a chapter by its note, or a message by its
 * text.
 */
export type ThreadSearchHit = { "kind": "chapter", chapterId: string, ts: number, title: string, excerpt: string, 
/**
 * The status column as the index holds it, which is a word the
 * indexer copied rather than one this build named.
 */
status?: string, } | { "kind": "message", eventId: string, chapterId?: string, ts: number, from: Side, excerpt: string, };

export type TokenUsage = { inputTokens?: number, outputTokens?: number, totalTokens?: number, };

/**
 * One line of a teammate's tool ledger.
 *
 * `reason` is required in every state, and that is the whole design. Tools
 * vanishing silently is the worst failure this project has shipped, and
 * every one of those bugs was an absence with an optional explanation
 * nobody filled in. A field that cannot be omitted cannot be forgotten.
 */
export type ToolLedgerRow = { name: string, source: ToolSourceKind, 
/**
 * The particular supplier, named: a server id, or `pi`.
 */
origin: string, state: ToolState, 
/**
 * Why this tool is in this state. Never empty.
 */
reason: string, 
/**
 * When Toad last observed it.
 */
at: number, };

export type ToolOutput = { "type": "text", text: string, } | { "type": "diff", path: string, 
/**
 * Written as `null` rather than omitted when there was no old text,
 * because that is what the ACP session writes and the record is
 * whatever it wrote.
 */
oldText?: string | null, newText: string, };

/**
 * Where one of a teammate's tools came from.
 *
 * Coarse on purpose: this names the mechanism that supplies the tool,
 * because that is what decides how an absence is fixed. `origin` beside it
 * names the particular supplier — an MCP server's id, `pi`.
 */
export type ToolSourceKind = "builtin" | "mcp";

/**
 * How sure Toad is about one tool.
 *
 * `verified` — Toad watched the agent take it: it built the tool array
 * itself. `declared` — Toad handed it over and cannot see what happened
 * next. `absent` — it is not there, and `reason` says why.
 */
export type ToolState = "verified" | "declared" | "absent";

export type ToolStatus = "pending" | "in_progress" | "completed" | "failed";

/**
 * One durable line in a teammate's transcript. Appended as JSONL and replayed
 * at startup. Note this is Toad's own record: replaying it is not the same as
 * the agent remembering the conversation.
 */
export type TranscriptEvent = { "kind": "user", id: string, ts: number, text: string, attachments?: Array<Attachment>, reactions?: Array<string>, replyTo?: string, 
/**
 * Nobody typed this: a schedule fired. The text stays the prompt in
 * full; this is what lets the transcript draw one line and keep the
 * prompt behind an expander.
 */
scheduled?: ScheduledRun, 
/**
 * An emphasis on this bubble.
 */
ring?: RingIntent, receipt?: Receipt, } | { "kind": "agent", id: string, ts: number, text: string, reactions?: Array<string>, 
/**
 * An emphasis on this bubble.
 */
ring?: RingIntent, receipt?: Receipt, } | { "kind": "thought", id: string, ts: number, text: string, } | { "kind": "tool", id: string, ts: number, toolCallId: string, title: string, toolKind?: string, status: ToolStatus, locations?: Array<string>, output?: Array<ToolOutput>, } | { "kind": "permission", id: string, ts: number, requestId: string, title: string, options: Array<PermissionOption>, decision?: string, decidedOptionName?: string, } | { "kind": "plan", id: string, ts: number, entries: Array<PlanEntry>, } | { "kind": "notice", id: string, ts: number, level: NoticeLevel, text: string, } | { "kind": "computer_frame", id: string, ts: number, dataUrl: string, } | { "kind": "human_action", id: string, ts: number, actionId: string, reason: string, status: HumanActionStatus, 
/**
 * What the person said with their answer, when they said anything.
 */
note?: string, } | { "kind": "peer", id: string, ts: number, threadKey: string, withPersonaId: string, withName: string, role: PeerRole, exchanges: number, status: PeerStatus, 
/**
 * What kind of citizen the other side is. Absent means a teammate —
 * every marker written before client seats existed, and every one
 * written for a teammate since. `client` means an outside MCP agent
 * holding a seat in this room; `withName` already carries the desk
 * it connected through, as in "Claude Code @ beastie".
 *
 * The field exists because the name alone cannot carry it: "Claude
 * Code @ beastie" and "Boris @ beastie" read identically, and a
 * message from outside the room must never look like one from a
 * teammate.
 */
seat?: PeerSeat, } | { "kind": "turn", id: string, ts: number, stopReason: string, usage?: TokenUsage, } | { "kind": "chapter", id: string, ts: number, backendId: string, sessionId?: string, endedAt?: number, title?: string, 
/**
 * The handoff note: goal, outcome, open loops, decisions, files.
 */
note?: string, status?: ChapterStatus, tags?: Array<string>, closedBy?: ChapterClose, 
/**
 * Set on a chapter that reopened an earlier one's context.
 */
resumedFrom?: string, };

/**
 * `transcriptAppended` and `transcriptUpdated`: one event, and whose tape it
 * belongs to. The two pushes differ in what the window does with the event,
 * not in what is on the wire.
 */
export type TranscriptPush = { personaId: string, event: TranscriptEvent, };

/**
 * The views the core maintains. One so far.
 */
export type ViewName = "roster";

/**
 * Which of the desk's web search a teammate gets — the same
 * inherit/override question `McpPolicy` answers for servers. Absent on the
 * teammate means `all`: inherit whatever the app's Tools pane has on. `some`
 * intersects with the app's choices — a provider the desk switched off stays
 * off for everyone.
 */
export type WebSearchPolicy = { mode: PolicyMode, providers: Array<WebSearchProvider>, };

export type WebSearchProvider = "parallel" | "exa" | "firecrawl" | "keenable";
